#ifndef STUDIO_EXTRA_ACTIONS_HPP
#define STUDIO_EXTRA_ACTIONS_HPP
bool App::extraAction(const std::string& op,int){
    if(op=="minimize"){ShowWindow(h,SW_MINIMIZE);return true;}if(op=="quit"){PostMessageW(h,WM_CLOSE,0,0);return true;}
    if(op=="crosshairs"||op=="rulers"){if(op=="crosshairs")crosshairs=!crosshairs;else rulers=!rulers;status=op=="crosshairs"?(crosshairs?"十字光标：开":"十字光标：关"):(rulers?"标尺：开":"标尺：关");return true;}
    if(op=="invert"){auto all=s.all();auto selected=studioio::expanded(s.doc,s.selected);s.selected.clear();for(auto r:all)if(!selected.count(r))s.selected.push_back(r);return true;}
    if(op=="nextStructure"||op=="previousStructure"){std::vector<std::set<ObjectId>> components;std::set<ObjectId> seen;for(auto& a:s.doc.atoms().records())if(a.isAlive()&&!seen.count(a.id)){std::set<ObjectId> part={a.id};bool changed=true;while(changed){changed=false;for(auto& b:s.doc.bonds().records())if(b.isAlive()&&(part.count(b.beginAtom)||part.count(b.endAtom))){changed|=part.insert(b.beginAtom).second;changed|=part.insert(b.endAtom).second;}}seen.insert(part.begin(),part.end());components.push_back(part);}if(components.empty())return true;int current=op=="previousStructure"?0:-1;for(auto r:s.selected)if(r.kind==ObjectKind::Atom){for(size_t i=0;i<components.size();i++)if(components[i].count(r.id))current=int(i);break;}auto& chosen=components[(current+(op=="previousStructure"?-1:1)+int(components.size()))%components.size()];s.selected.clear();for(auto id:chosen)s.selected.push_back(ObjectRef(ObjectKind::Atom,id));for(auto& b:s.doc.bonds().records())if(b.isAlive()&&chosen.count(b.beginAtom)&&chosen.count(b.endAtom))s.selected.push_back(ObjectRef(ObjectKind::Bond,b.id));return true;}
    if(op=="front"||op=="back"){auto refs=studioio::expanded(s.doc,s.selected);int z=0;for(auto r:s.all())if(auto value=s.doc.extensions(r).findValue("studio.z"))z=op=="front"?std::max(z,atoi(value->c_str())):std::min(z,atoi(value->c_str()));z+=op=="front"?100:-100;error(s.submit(Command("堆叠顺序",kInvalidateAppearance,[refs,z](CommandContext& c){for(auto r:refs)c.document.extensions(r).set("studio.z",std::to_string(z));return CommandResult::success();}),"堆叠顺序"));return true;}
    if(op=="autoLabel"){auto refs=studioio::expanded(s.doc,s.selected);error(s.submit(Command("自动标签方向",kInvalidateAppearance,[refs](CommandContext& c){for(auto r:refs)if(r.kind==ObjectKind::Atom)c.document.extensions(r).set("studio.label.automatic","1");return CommandResult::success();}),"自动标签方向"));return true;}
    if(op=="kekulize"){auto refs=chemicalScope();bool aromatic=false;for(auto r:refs)if(r.kind==ObjectKind::Bond){auto b=s.doc.bonds().get(r.id);aromatic|=b->order==BondOrder::Aromatic||b->semantics==BondSemantics::Aromatic;}error(s.submit(Command("切换 Kekulé 表示",kInvalidateAppearance|kInvalidateStructure,[refs,aromatic](CommandContext& c){std::set<ObjectId> doubled;for(auto r:refs)if(r.kind==ObjectKind::Bond){auto b=c.document.bonds().get(r.id);if(!aromatic){if(b->order==BondOrder::Double)c.document.setBondSemantics(r.id,BondSemantics::Aromatic);}else if(b->order==BondOrder::Aromatic){bool useDouble=!doubled.count(b->beginAtom)&&!doubled.count(b->endAtom);c.document.setBondOrder(r.id,useDouble?BondOrder::Double:BondOrder::Single);if(useDouble){doubled.insert(b->beginAtom);doubled.insert(b->endAtom);}}if(aromatic)c.document.setBondSemantics(r.id,BondSemantics::Normal);}return CommandResult::success();}),"Kekulé 表示"));return true;}
    if(op=="perspective"){s.activateCommand("chooseSelectionTool_Marquee");auto cam=advanced::readCamera(s.doc);cam.enabled=!cam.enabled;cam.yawDeg=cam.enabled?25:0;cam.pitchDeg=cam.enabled?15:0;error(s.submit(advanced::applyPerspectiveCommand(cam,{}),"结构透视"));status=cam.enabled?"结构透视：开":"结构透视：关";return true;}
    if(op=="print"){PRINTDLGW p={};p.lStructSize=sizeof(p);p.hwndOwner=h;p.Flags=PD_RETURNDC|PD_NOSELECTION|PD_USEDEVMODECOPIESANDCOLLATE;p.nMinPage=1;auto paper=studioio::Page::get(s.doc);p.nMaxPage=WORD(paper.across*paper.down);p.nFromPage=1;p.nToPage=p.nMaxPage;if(PrintDlgW(&p)){DOCINFOW doc={};doc.cbSize=sizeof(doc);doc.lpszDocName=L"Molecule Studio";if(StartDocW(p.hDC,&doc)>0){bool failed=false;for(int y=0;y<paper.down&&!failed;y++)for(int x=0;x<paper.across&&!failed;x++){int page=y*paper.across+x+1;if((p.Flags&PD_PAGENUMS)&&(page<p.nFromPage||page>p.nToPage))continue;if(StartPage(p.hDC)<=0){failed=true;break;}Graphics g(p.hDC);g.SetPageUnit(UnitPixel);g.SetSmoothingMode(SmoothingModeAntiAlias);double scale=std::min(GetDeviceCaps(p.hDC,HORZRES)/paper.width,GetDeviceCaps(p.hDC,VERTRES)/paper.height);g.ScaleTransform(float(scale),float(scale));g.TranslateTransform(float(-paper.x-x*paper.width),float(-paper.y-y*paper.height));for(auto& prim:s.scene.primitives()){GraphicsPath path(prim.style.fillRule==render::FillRule::EvenOdd?FillModeAlternate:FillModeWinding);auto add=[&](const std::vector<Vec2>& points,bool closed){if(points.size()<2)return;std::vector<PointF> pts;for(auto pt:points)pts.emplace_back(float(pt.x),float(pt.y));path.StartFigure();path.AddLines(pts.data(),INT(pts.size()));if(closed)path.CloseFigure();};if(!prim.subpaths.empty())for(auto& sub:prim.subpaths)add(sub.points,sub.closed);else{std::vector<Vec2> pts;bool closed=false;render::geom::FlattenOptions f;f.tolerance=.05;if(render::geom::flattenPath(prim,f,&pts,&closed))add(pts,closed);}auto color=[](uint32_t c){c=render::resolvePaint(c);return Color(BYTE(c),BYTE(c>>24),BYTE(c>>16),BYTE(c>>8));};if(prim.style.fill.enabled){SolidBrush fill(color(prim.style.fill.rgba));g.FillPath(&fill,&path);}if(prim.style.stroke.enabled){Pen pen(color(prim.style.stroke.rgba),float(prim.style.strokeWidth>0?prim.style.strokeWidth:s.doc.defaultLineWidth()));if(!prim.style.dash.solid())pen.SetDashStyle(DashStyleDash);g.DrawPath(&pen,&path);}}if(EndPage(p.hDC)<=0)failed=true;}if(failed)AbortDoc(p.hDC);else EndDoc(p.hDC);status=failed?"打印未完成":"已发送到打印机";}DeleteDC(p.hDC);}if(p.hDevMode)GlobalFree(p.hDevMode);if(p.hDevNames)GlobalFree(p.hDevNames);return true;}
    if(op=="help"){studio_i18n::messageBox(h,L"MoleculeStudio 默认快捷键。\n\n原子、化学键、空白画布分别使用各自的热点快捷键。\n= 打开完整缩写库；/ 或 ? 编辑热点属性。\nCtrl+Alt+N：结构转系统名称\nCtrl+Shift+N：名称转结构\nCtrl+Shift+K：整理结构\nCtrl+Shift+D：三维构象整理\nCtrl+Shift+X：整理反应\n\n设置 → 快捷键：查看、更改或恢复全部默认键。",L"Molecule Studio 帮助",MB_OK);return true;}
    if(op=="splitter"){splitter=!splitter;status=splitter?"已打开文档概览，点击概览定位":"已关闭文档概览";return true;}
    return false;
}
#endif
